class TestTransactions:
    """Tests for begin/commit/rollback semantics."""

    def test_commit_persists_changes(self, storage: StorageMock):
        """Committed changes are visible after the transaction."""
        storage.begin()
        storage.set("tx_key", "tx_value")
        storage.commit()
        assert storage.get("tx_key") == "tx_value"

    def test_rollback_discards_changes(self, storage: StorageMock):
        """Rolled-back changes are not visible."""
        storage.begin()
        storage.set("temp_key", "temp_value")
        storage.rollback()
        with pytest.raises(StorageError):
            storage.get("temp_key")

    def test_rollback_restores_original(self, populated_storage: StorageMock):
        """Rollback restores the state from before the transaction."""
        original = populated_storage.get("key_0")
        populated_storage.begin()
        populated_storage.set("key_0", {"mutated": True})
        populated_storage.rollback()
        assert populated_storage.get("key_0") == original

    def test_nested_transactions_commit(self, storage: StorageMock):
        """Nested transactions commit correctly."""
        storage.begin()
        storage.set("outer", 1)
        storage.begin()
        storage.set("inner", 2)
        storage.commit()  # inner commit
        storage.commit()  # outer commit
        assert storage.get("outer") == 1
        assert storage.get("inner") == 2

    def test_nested_transactions_rollback_inner(self, storage: StorageMock):
        """Rolling back inner transaction preserves outer changes."""
        storage.begin()
        storage.set("outer", 1)
        storage.begin()
        storage.set("inner", 2)
        storage.rollback()  # inner rollback
        storage.commit()  # outer commit
        assert storage.get("outer") == 1
        with pytest.raises(StorageError):
            storage.get("inner")

    def test_commit_without_begin_raises(self, storage: StorageMock):
        """Committing without an active transaction raises TransactionError."""
        with pytest.raises(TransactionError):
            storage.commit()

    def test_rollback_without_begin_raises(self, storage: StorageMock):
        """Rolling back without an active transaction raises TransactionError."""
        with pytest.raises(TransactionError):
            storage.rollback()

    def test_operations_inside_transaction(self, storage: StorageMock):
        """All CRUD operations work inside a transaction."""
        storage.begin()
        storage.set("a", 1)
        storage.set("b", 2)
        storage.delete("a")
        assert storage.get("b") == 2
        with pytest.raises(StorageError):
            storage.get("a")
        storage.commit()
        assert storage.get("b") == 2


