class TestCrashConsistency:
    """Tests for crash-consistency simulation."""

    def test_simulate_crash_discards_uncommitted(self, storage: StorageMock):
        """Simulated crash discards uncommitted transaction data."""
        storage.begin()
        storage.set("volatile", "data")
        storage.simulate_crash()
        with pytest.raises(StorageError):
            storage.get("volatile")

    def test_simulate_crash_preserves_committed(self, storage: StorageMock):
        """Simulated crash preserves committed data."""
        storage.begin()
        storage.set("durable", "data")
        storage.commit()
        storage.simulate_crash()
        assert storage.get("durable") == "data"

    def test_simulate_crash_clears_active_transaction(self, storage: StorageMock):
        """After crash, no active transaction remains."""
        storage.begin()
        storage.set("x", 1)
        storage.simulate_crash()
        # Should be able to start a new transaction cleanly
        storage.begin()
        storage.set("y", 2)
        storage.commit()
        assert storage.get("y") == 2

    def test_crash_during_transaction_rollback(self, storage: StorageMock):
        """Crash during rollback leaves storage in consistent state."""
        storage.set("stable", "original")
        storage.begin()
        storage.set("stable", "modified")
        storage.simulate_crash()
        # Storage should revert to last committed state
        assert storage.get("stable") == "original"


