class TestIsolationLevels:
    """Tests for isolation level semantics."""

    def test_read_committed_sees_committed_only(self, storage_rc: StorageMock):
        """READ_COMMITTED sees only committed data."""
        storage_rc.begin()
        storage_rc.set("pending", "uncommitted")
        # Within the same transaction, the write is visible
        assert storage_rc.get("pending") == "uncommitted"
        storage_rc.rollback()
        with pytest.raises(StorageError):
            storage_rc.get("pending")

    def test_repeatable_read_snapshot(self, storage_rr: StorageMock):
        """REPEATABLE_READ provides a consistent snapshot."""
        storage_rr.set("base", 100)
        storage_rr.begin()
        first_read = storage_rr.get("base")
        # Simulate concurrent modification (bypassing transaction)
        storage_rr._data["base"] = 200
        second_read = storage_rr.get("base")
        assert first_read == second_read == 100
        storage_rr.rollback()

    def test_serializable_prevents_phantom(self, storage_serializable: StorageMock):
        """SERIALIZABLE prevents phantom reads."""
        storage_serializable.set("a", 1)
        storage_serializable.begin()
        initial_keys = set(storage_serializable.keys())
        # Simulate concurrent insert
        storage_serializable._data["phantom"] = 999
        current_keys = set(storage_serializable.keys())
        assert current_keys == initial_keys  # Phantom not visible
        storage_serializable.rollback()

    def test_isolation_level_enum_values(self):
        """IsolationLevel enum has expected members."""
        assert IsolationLevel.READ_COMMITTED.value == "READ_COMMITTED"
        assert IsolationLevel.REPEATABLE_READ.value == "REPEATABLE_READ"
        assert IsolationLevel.SERIALIZABLE.value == "SERIALIZABLE"


