class TestConcurrency:
    """Tests for asyncio.Lock-based concurrency safety."""

    @pytest.mark.asyncio
    async def test_concurrent_writes(self, storage: StorageMock):
        """Concurrent writes are serialized and all succeed."""
        async def write_value(key: str, value: int):
            async with storage._lock:
                storage.set(key, value)

        tasks = [write_value(f"key_{i}", i) for i in range(50)]
        await asyncio.gather(*tasks)
        for i in range(50):
            assert storage.get(f"key_{i}") == i

    @pytest.mark.asyncio
    async def test_concurrent_read_write(self, storage: StorageMock):
        """Concurrent reads and writes do not corrupt state."""
        storage.set("counter", 0)

        async def increment():
            for _ in range(10):
                async with storage._lock:
                    current = storage.get("counter")
                    storage.set("counter", current + 1)

        await asyncio.gather(*[increment() for _ in range(10)])
        assert storage.get("counter") == 100

    @pytest.mark.asyncio
    async def test_lock_is_reentrant(self, storage: StorageMock):
        """The lock can be acquired multiple times by the same task."""
        async with storage._lock:
            async with storage._lock:
                storage.set("nested", True)
        assert storage.get("nested") is True

    @pytest.mark.asyncio
    async def test_concurrent_transactions(self, storage: StorageMock):
        """Concurrent transactions do not interfere."""
        async def run_transaction(tx_id: int):
            storage.begin()
            storage.set(f"tx_{tx_id}", tx_id)
            await asyncio.sleep(0.01)  # Simulate work
            storage.commit()

        await asyncio.gather(*[run_transaction(i) for i in range(20)])
        for i in range(20):
            assert storage.get(f"tx_{i}") == i


