class TestPropertyBased:
    """Property-based tests using hypothesis."""

    @given(st.text(min_size=1, max_size=50), st.integers())
    @settings(max_examples=100)
    def test_set_get_roundtrip(self, key: str, value: int):
        """For any key-value pair, set followed by get returns the value."""
        storage = StorageMock(seed=random.randint(0, 1000))
        storage.set(key, value)
        assert storage.get(key) == value

    @given(st.lists(st.tuples(st.text(), st.integers()), min_size=1, max_size=20))
    @settings(max_examples=50)
    def test_multiple_set_get(self, pairs: list):
        """Multiple set operations are all retrievable."""
        storage = StorageMock(seed=random.randint(0, 1000))
        for key, value in pairs:
            storage.set(key, value)
        for key, value in pairs:
            assert storage.get(key) == value

    @given(st.dictionaries(st.text(), st.integers(), min_size=1, max_size=10))
    @settings(max_examples=50)
    def test_dictionary_bulk_operations(self, data: dict):
        """Bulk dictionary operations maintain consistency."""
        storage = StorageMock(seed=random.randint(0, 1000))
        for key, value in data.items():
            storage.set(key, value)
        assert storage.size() == len(data)
        for key, value in data.items():
            assert storage.get(key) == value

    @given(st.text(min_size=1), st.integers())
    @settings(max_examples=50)
    def test_delete_removes_key(self, key: str, value: int):
        """Deleting a key makes it inaccessible."""
        storage = StorageMock(seed=random.randint(0, 1000))
        storage.set(key, value)
        storage.delete(key)
        assert not storage.contains(key)
        with pytest.raises(StorageError):
            storage.get(key)

    @given(st.lists(st.integers(), min_size=1, max_size=100))
    @settings(max_examples=50)
    def test_transaction_commit_all(self, values: list):
        """All values committed in a transaction are persisted."""
        storage = StorageMock(seed=random.randint(0, 1000))
        storage.begin()
        for i, value in enumerate(values):
            storage.set(f"key_{i}", value)
        storage.commit()
        for i, value in enumerate(values):
            assert storage.get(f"key_{i}") == value

    @given(st.lists(st.integers(), min_size=1, max_size=100))
    @settings(max_examples=50)
    def test_transaction_rollback_all(self, values: list):
        """All values rolled back in a transaction are discarded."""
        storage = StorageMock(seed=random.randint(0, 1000))
        storage.begin()
        for i, value in enumerate(values):
            storage.set(f"key_{i}", value)
        storage.rollback()
        assert storage.size() == 0

    @given(st.text(min_size=1), st.integers())
    @settings(max_examples=50)
    def test_overwrite_preserves_latest(self, key: str, value: int):
        """Overwriting a key always yields the latest value."""
        storage = StorageMock(seed=random.randint(0, 1000))
        storage.set(key, value)
        new_value = value + 1
        storage.set(key, new_value)
        assert storage.get(key) == new_value


