class TestIntegrationScenarios:
    """End-to-end scenarios combining multiple features."""

    def test_full_workflow(self, storage: StorageMock):
        """Complete workflow: CRUD + transactions + crash recovery."""
        # Phase 1: Initial data
        storage.set("user:1", {"name": "Alice", "balance": 100})
        storage.set("user:2", {"name": "Bob", "balance": 50})

        # Phase 2: Transactional transfer
        storage.begin()
        alice = storage.get("user:1")
        bob = storage.get("user:2")
        alice["balance"] -= 30
        bob["balance"] += 30
        storage.set("user:1", alice)
        storage.set("user:2", bob)
        storage.commit()

        assert storage.get("user:1")["balance"] == 70
        assert storage.get("user:2")["balance"] == 80

        # Phase 3: Crash simulation
        storage.begin()
        storage.set("user:3", {"name": "Charlie", "balance": 1000})
        storage.simulate_crash()

        assert not storage.contains("user:3")
        assert storage.get("user:1")["balance"] == 70  # Committed data survives

    def test_concurrent_user_sessions(self, storage: StorageMock):
        """Simulated concurrent user sessions with transactions."""
        storage.set("inventory", {"items": 100})

        async def purchase(user_id: str, quantity: int):
            async with storage._lock:
                storage.begin()
                inventory = storage.get("inventory")
                if inventory["items"] >= quantity:
                    inventory["items"] -= quantity
                    storage.set("inventory", inventory)
                    storage.commit()
                    return True
                storage.rollback()
                return False

        async def run_purchases():
            results = await asyncio.gather(
                purchase("user_a", 30),
                purchase("user_b", 40),
                purchase("user_c", 50),
            )
            return results

        results = asyncio.run(run_purchases())
        assert sum(results) == 2  # Only two purchases succeed (30+40=70, 50 fails)
        assert storage.get("inventory")["items"] == 30  # 100 - 30 - 40 = 30

    def test_data_integrity_after_many_operations(self, storage: StorageMock):
        """Data integrity maintained after many mixed operations."""
        expected: Dict[str, Any] = {}
        for i in range(100):
            key = f"key_{i}"
            value = {"index": i, "data": f"value_{i}"}
            storage.set(key, value)
            expected[key] = value

        # Perform some deletions and updates
        for i in range(0, 100, 10):
            storage.delete(f"key_{i}")
            del expected[f"key_{i}"]

        for i in range(5, 100, 10):
            new_value = {"index": i, "data": f"updated_{i}"}
            storage.set(f"key_{i}", new_value)
            expected[f"key_{i}"] = new_value

        # Verify all expected values
        assert storage.size() == len(expected)
        for key, value in expected.items():
            assert storage.get(key) == value


